    # A horizontal-then-vertical route is used for each selected edge.
    if len(pts) < 2:
        return out
    connected = {pts[0]}
    remaining = set(pts[1:])
    while remaining:
        best = None
        for a in connected:
            for b in remaining:
                d = abs(a[0] - b[0]) + abs(a[1] - b[1])
                cand = (d, a, b)
                if best is None or cand < best:
                    best = cand
        _, (r1, c1), (r2, c2) = best
        for c in range(min(c1, c2), max(c1, c2) + 1):
            if out[r1][c] == 0:
