    if not pts:
        return out

    rows = sorted(r for r, c in pts)
    mid = rows[(len(rows) - 1) // 2]
    left = min(c for r, c in pts)
    right = max(c for r, c in pts)

    for c in range(left, right + 1):
        if out[mid][c] == 0:
            out[mid][c] = 3
    for r, c in pts:
        for rr in range(min(r, mid), max(r, mid) + 1):
            if out[rr][c] == 0:
                out[rr][c] = 3
    return out
